const nock = require("nock");
nock.disableNetConnect();
nock("https://maps.googleapis.com")
  .get("/maps/api/place/details/json?fields=place_id,name&key=foo&place_id=notarealid")
  .reply(200, JSON.stringify({ status: "NOT_FOUND" }), { "Content-Type": "application/json" });

require("ts-node/register/transpile-only");
const { Client } = require("./src/client");

(async () => {
  const client = new Client();
  try {
    const r = await client.placeDetails({ params: { place_id: "notarealid", key: "foo", fields: ["place_id","name"] } });
    console.log("RESOLVED, status in config:", r.config && r.config.validateStatus && String(r.config.validateStatus).slice(0,300));
    console.log("response status:", r.status, "data:", r.data);
  } catch (e) {
    console.log("REJECTED:", e.message, e.code);
  }
  process.exit(0);
})().catch(e => { console.log("ERR", e); process.exit(1); });
EOF
